interface CartState {
  items: string[];
}

@Injectable({ providedIn: 'root' })
export class CartStore {
  private state = new BehaviorSubject<CartState>({ items: [] });
  state$ = this.state.asObservable();

  addItem(item: string) {
    const current = this.state.value.items;
    this.state.next({ items: [...current, item] });
  }

  removeItem(item: string) {
    const current = this.state.value.items;
    this.state.next({ items: current.filter(i => i !== item) });
  }
}

@Component({
  selector: 'app-cart',
  template: `
    <ul>
      <li *ngFor="let item of store.state$ | async as state">
        {{ item }}
      </li>
    </ul>
  `
})
export class CartComponent {
  constructor(public store: CartStore) {}
}
